import React, { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

export type SelectV2CustomTriggerProps = PropsWithChildren;

/**
 * Typeguard function that will check if a React.Node is a SelectV2.CustomTrigger
 * @internal
 */
export function _isSelectV2CustomTriggerElement(
  child: React.ReactNode,
): child is React.ReactElement<SelectV2CustomTriggerProps> {
  if (isElement(child) && child.type === SelectV2CustomTrigger) {
    return true;
  }
  return false;
}

export function SelectV2CustomTrigger(props: SelectV2CustomTriggerProps) {
  return null;
}
SelectV2CustomTrigger.displayName = 'SelectV2.CustomTrigger';
